    if ("performance".equals(args[0])) {
        if (args.length != 2) throw new IllegalArgumentException("performance requires a data directory");
        Stage6Performance.run(java.nio.file.Path.of(args[1]));
        return;
    }
    if (!"provider-smoke".equals(args[0]) || args.length != 1) {
        throw new IllegalArgumentException("usage: provider-smoke | performance <directory>");
    }
    smoke("openai", System.getenv("JI_TEST_OPENAI_BASE_URL"), System.getenv("JI_TEST_OPENAI_API_KEY"),
            System.getenv("JI_TEST_OPENAI_MODEL"));

